// Nach der Bestätigung – Dokumente, die dem RAG hinzugefügt werden: der von der Pflegekraft BESTÄTIGTE Text (gelesen, gegebenenfalls korrigiert),
// gelesen in der Tabelle der Bestätigungen (maßgebliche Quelle), nie der rohe Text der KI und nie ein von außen empfangener Text.
// Ein bestätigter Bericht wird mit der Quelle « Bestätigter Bericht » und dem Typ « rapport_valide » indexiert: Neue
// SBAR-Berichte lesen ihn nicht als Fakt erneut (siehe « Suchen »), er bleibt aber für den Modus B abrufbar.
const fmt = (d) => {
  const p = new Intl.DateTimeFormat('de-DE', { timeZone: 'Europe/Berlin', day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).formatToParts(new Date(d));
  const g = (t) => p.find((x) => x.type === t).value;
  return `${g('day')}.${g('month')}. ${g('hour')}:${g('minute')} Uhr`;
};
const lignes = $input.all().map((i) => i.json).filter((r) => r.validation_id);
return lignes.map((r) => ({
  json: {
    collection: 'patients',
    texte: r.texte,
    titre: `Bestätigter Dienstbericht (SBAR), ${fmt(r.valide_le)}`,
    source: 'validation',
    source_label: 'Bestätigter Bericht',
    source_ref: `validation-${r.validation_id}`,
    type: 'rapport_valide',
    patient_id: r.patient_id,
    chambre: r.chambre,
    patient_label: `${r.civilite} ${r.prenom} ${r.nom} (Zimmer ${r.chambre})`,
    date: new Date(r.valide_le).toISOString(),
  },
}));

// Nach der Bestätigung – Übergabenachricht an das nächste Team: die BESTÄTIGTEN Texte (gelesen in der Tabelle der
// Bestätigungen), mit ihren Quellen und dem Namen der Pflegekraft, die sie bestätigt hat.
const DESTINATAIRE = 'equipe-suivante@sonnenhof.example.test';
const entree = $('Eingang').first().json;
const rapports = $('Bestätigte Berichte').all().map((i) => i.json).filter((r) => r.validation_id);
if (!rapports.length) throw new Error('Kein bestätigter Bericht zur Weitergabe.');

const fmt = (d) => {
  const p = new Intl.DateTimeFormat('de-DE', { timeZone: 'Europe/Berlin', day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).formatToParts(new Date(d));
  const g = (t) => p.find((x) => x.type === t).value;
  return { jour: `${g('day')}.${g('month')}.${g('year')}`, heure: `${g('hour')}:${g('minute')} Uhr` };
};
const portee = entree.portee === 'etage' ? 'etage' : 'resident';
const etage = portee === 'etage' ? Number(entree.etage) : null;
const maintenant = fmt(new Date());
const sujet = portee === 'etage'
  ? `Dienstübergabe – Etage ${etage} – ${maintenant.jour} ${maintenant.heure}`
  : `Dienstübergabe – Zimmer ${rapports[0].chambre} (${rapports[0].civilite} ${rapports[0].nom}) – ${maintenant.jour} ${maintenant.heure}`;

const blocs = rapports.map((r) => {
  const v = fmt(r.valide_le);
  const sources = (Array.isArray(r.sources) ? r.sources : []).map((s) => `[${s}]`).join(' ');
  return [
    `=== Zimmer ${r.chambre} – ${r.civilite} ${r.prenom} ${r.nom} (Etage ${r.etage}) ===`,
    r.texte.trim(),
    `Quellen: ${sources || 'keine'}`,
    `Bestätigt von ${r.valide_par} am ${v.jour} um ${v.heure}.`,
  ].join('\n');
});
const texte = [
  sujet,
  '',
  'Diese Nachricht enthält die Dienstberichte der letzten 12 Stunden, die von einer Pflegekraft gelesen und bestätigt wurden. Sie wurden mit Hilfe eines KI-Assistenten für Pflegeteams verfasst; im Zweifelsfall ist die Pflegedokumentation maßgeblich.',
  '',
  blocs.join('\n\n'),
].join('\n');

return [
  {
    json: {
      sujet,
      texte,
      destinataire: DESTINATAIRE,
      portee,
      etage,
      patient_ids: rapports.map((r) => r.patient_id),
      validation_ids: rapports.map((r) => r.validation_id),
      mailpit: {
        From: { Email: 'transmission@sonnenhof.example.test', Name: 'AI-Care – Dienstübergabe' },
        To: [{ Email: DESTINATAIRE, Name: 'Nächstes Team' }],
        Subject: sujet,
        Text: texte,
      },
    },
  },
];

// Nach der Bestätigung – Ergebnis: wie viele Berichte dem RAG hinzugefügt wurden und die Weitergabe (gesendet oder fehlgeschlagen).
const m = $('Übergabenachricht').first().json;
const envoi = $('Senden (Mailpit)').first().json;
const note = $('Übergabe vermerken').first().json;
const rag = $('Indizieren (RAG)').first().json ?? {};
const echec = Boolean(envoi?.error);
return [
  {
    json: {
      rag: { ajoutes: rag.morceaux_indexes ?? 0, ignores_deja_importes: rag.ignores_deja_importes ?? 0 },
      transmission: {
        id: note.id,
        statut: echec ? 'echec' : 'envoye',
        destinataire: m.destinataire,
        sujet: m.sujet,
        portee: m.portee,
        nb_rapports: m.validation_ids.length,
      },
      evenements_journal: [
        {
          evenement: 'ajout_rag',
          patient_id: m.patient_ids.length === 1 ? m.patient_ids[0] : null,
          mode: 'a',
          action: 'generer_sbar',
          details: { validations: m.validation_ids, morceaux: rag.morceaux_indexes ?? 0 },
        },
        {
          evenement: 'transmission',
          patient_id: m.patient_ids.length === 1 ? m.patient_ids[0] : null,
          mode: 'a',
          action: 'generer_sbar',
          details: { transmission_id: note.id, statut: echec ? 'echec' : 'envoye', portee: m.portee, etage: m.etage, validations: m.validation_ids },
        },
      ],
    },
  },
];

// Nach der Bestätigung – Ausgang des Unter-Workflows (ohne die Protokollereignisse).
const { evenements_journal, ...resultat } = $('Zusammenfassung').first().json;
return [{ json: resultat }];
